#!/bin/sh
# The marine is now generated by K12 (tools/assets/k12-hero). This script rebuilds the KA12 arsenal and
# delegates the marine so it can never overwrite marine.glb with the first-generation body.
set -eu
cd "$(dirname "$0")/../../.."
blender -b -t 4 -P tools/assets/ka12-weapons/weapons.py -- --round=3 --ship
sh tools/assets/k12-hero/rebuild.sh
